test('mergeCustomers merges two customers successfully', () => {
  const customers = listCustomers();
  const invoices = [
    issueInvoice(createInvoice({
      customerId: 'C-002',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }).value, []).value,
    issueInvoice(createInvoice({
      customerId: 'C-003',
      issueDate: '2026-10-08',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }).value, ['INV-2026-0001']).value,
  ];

  const r = mergeCustomers(customers, invoices, 'C-002', 'C-003');

  assert.equal(r.ok, true);
  // C-002 should be removed
  assert(!r.value.customers.find(c => c.id === 'C-002'));
  // C-003 should still exist
  assert(r.value.customers.find(c => c.id === 'C-003'));
  // Both invoices should now be for C-003
  assert.equal(r.value.invoices[0].customerId, 'C-003');
  assert.equal(r.value.invoices[1].customerId, 'C-003');
});

test('mergeCustomers returns CUSTOMER_NOT_FOUND if fromId does not exist', () => {
  const customers = listCustomers();
  const r = mergeCustomers(customers, [], 'C-999', 'C-002');

  assert.equal(r.ok, false);
  assert.equal(r.error, 'CUSTOMER_NOT_FOUND');
});

test('mergeCustomers returns CUSTOMER_NOT_FOUND if intoId does not exist', () => {
  const customers = listCustomers();
  const r = mergeCustomers(customers, [], 'C-002', 'C-999');

  assert.equal(r.ok, false);
  assert.equal(r.error, 'CUSTOMER_NOT_FOUND');
});

test('mergeCustomers returns SAME_CUSTOMER if both ids are the same', () => {
  const customers = listCustomers();
  const r = mergeCustomers(customers, [], 'C-002', 'C-002');

  assert.equal(r.ok, false);
  assert.equal(r.error, 'SAME_CUSTOMER');
});

test('mergeCustomers normalizes customer ids', () => {
  const customers = listCustomers();
  const r = mergeCustomers(customers, [], ' c-002 ', 'C-003');

  assert.equal(r.ok, true);
  assert(!r.value.customers.find(c => c.id === 'C-002'));
});

test('mergeCustomers transfers all invoices from fromId', () => {
  const customers = listCustomers();
  const invoices = [
    issueInvoice(createInvoice({
      customerId: 'C-002',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }).value, []).value,
    issueInvoice(createInvoice({
      customerId: 'C-002',
      issueDate: '2026-10-08',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }).value, ['INV-2026-0001']).value,
    issueInvoice(createInvoice({
      customerId: 'C-003',
      issueDate: '2026-10-09',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }).value, ['INV-2026-0001', 'INV-2026-0002']).value,
  ];

  const r = mergeCustomers(customers, invoices, 'C-002', 'C-003');

  assert.equal(r.ok, true);
  // All invoices should be for C-003
  assert.equal(r.value.invoices.filter(inv => inv.customerId === 'C-003').length, 3);
});

test('mergeCustomers does not mutate original arrays', () => {
  const customers = listCustomers();
  const invoices = [
    issueInvoice(createInvoice({
      customerId: 'C-002',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    }).value, []).value,
  ];

  const customersSnapshot = JSON.stringify(customers);
  const invoicesSnapshot = JSON.stringify(invoices);

  mergeCustomers(customers, invoices, 'C-002', 'C-003');

  assert.equal(JSON.stringify(customers), customersSnapshot);
  assert.equal(JSON.stringify(invoices), invoicesSnapshot);
});

test('mergeCustomers handles empty invoice array', () => {
  const customers = listCustomers();
  const r = mergeCustomers(customers, [], 'C-002', 'C-003');

  assert.equal(r.ok, true);
  assert.equal(r.value.invoices.length, 0);
  assert(!r.value.customers.find(c => c.id === 'C-002'));
});

